-- Rollback: UPDATE control_registry SET evidence = replace(evidence, ' | CONTROL-ALT-PROBES-3 2026-10-19: probed by its control_alternate_probes row (third seed, controls whose alternate leaves a D1 trace), which the chaos drill runs every 360 minutes, and only a passing probe stamps alternate_tested_at', '') WHERE evidence LIKE '%CONTROL-ALT-PROBES-3 2026-10-19%'; UPDATE control_registry SET evidence = replace(evidence, ' | PATHS-UNTESTED-1 (CONTROL-ALT-PROBES-3 2026-10-19): ALTERNATE-NOT-EXERCISABLE: the alternate is the post-merge push run and the 2-hourly schedule of the model-floor-guard workflow on GitHub Actions, and D1 holds no record of a run. Read 2026-10-19 (SELECT only): no table or view of workflow runs, no cloud_ops_events kind for it, and qnfo-github-steward keeps the workflow only as a notification when a run FAILS (github_steward_runs.detail, 2026-10-18 and 2026-10-19), so a green run leaves nothing and a probe could only pass by absence. alternate_tested_at stays NULL on purpose, and a control_alternate_probes row, once a record of the run exists, takes precedence over this reason.', '') WHERE control = 'model_floor_pr_check'; UPDATE control_registry SET evidence = replace(evidence, ' | PATHS-UNTESTED-1 (CONTROL-ALT-PROBES-3 2026-10-19): ALTERNATE-NOT-EXERCISABLE: the gauge is a per-isolate variable (_aiRateSkip in qnfo-research-exec aiText) and its alternate is a fallback model or a 20 second wait. D1 sees it only as cloud_ops_events kind ai-skip while a provider rate limit is in progress. Read 2026-10-19 (SELECT only): 0 ai-skip events ever, and 1 rate-limit event (3021 or 3040) on 2026-10-19 against 4132 on 2026-10-17 and 2026-10-18, so an event-in-window probe would fail until the provider limits again and a state probe would stamp a declaration. The logic is pinned offline by qnfo-research-exec/width-governor.test.mjs. alternate_tested_at stays NULL on purpose, and a control_alternate_probes row takes precedence over this reason.', '') WHERE control = 'research-model-skip-gauge'; UPDATE control_registry SET evidence = replace(evidence, ' | PATHS-UNTESTED-1 (CONTROL-ALT-PROBES-3 2026-10-19): ALTERNATE-NOT-EXERCISABLE: the guard is a rule in code (aiFallbackFor against the AI_RATE_FALLBACK and __AI_ATTR_RATES constants of qnfo-research-exec) and its alternate, to wait one gauge window and try once more, leaves a cloud_ops_events row (kind ai-warn, text no fallback at or under its price) only when a call is rate limited. Read 2026-10-19 (SELECT only): 0 such events ever, 0 ai-skip events ever, and the only fallback events are 17 kimi-k2.6 timeouts that took the cheaper glm-5.3-flash, so a probe could only pass by absence. The rule is pinned offline by qnfo-research-exec/width-governor.test.mjs (a table entry naming a dearer model is refused at run time). alternate_tested_at stays NULL on purpose, and a control_alternate_probes row takes precedence over this reason.', '') WHERE control = 'research-fallback-price-guard'; DELETE FROM control_alternate_probes WHERE control IN ('code-task-publish-patch-cap', 'relapse-reopen-window', 'verification-deferral-escalation', 'improvement-loop-relapse-trigger-judge'); DELETE FROM blocker_redteam WHERE target IN ('control:model_floor_pr_check', 'control:research-model-skip-gauge', 'control:research-fallback-price-guard'); DELETE FROM remediation_contracts WHERE class IN ('fm-control-alternate-reason-unread', 'belief-alt-unexercisable-model_floor_pr_check', 'belief-alt-unexercisable-research-model-skip-gauge', 'belief-alt-unexercisable-research-fallback-price-guard'); DELETE FROM belief_registry WHERE belief_key IN ('alt-unexercisable-model_floor_pr_check', 'alt-unexercisable-research-model-skip-gauge', 'alt-unexercisable-research-fallback-price-guard'); UPDATE agent_issues SET status = 'superseded' WHERE title LIKE 'MODEL-FLOOR-GUARD-OBSERVABLE-1:%' AND status = 'open'; DELETE FROM failure_modes WHERE fm_key = 'control-alternate-reason-unread'; DROP VIEW IF EXISTS v_control_alternate_status; CREATE VIEW v_control_alternate_status AS SELECT c.control AS control, c.critical_path AS critical_path, c.disposition AS disposition, c.disposition_state AS disposition_state, c.alternate_path AS alternate_path, c.alternate_tested_at AS alternate_tested_at, p.enabled AS probe_enabled, p.last_run_at AS last_run_at, p.last_pass AS last_pass, p.last_pass_at AS last_pass_at, p.last_observed AS last_observed, p.window_note AS window_note, CASE WHEN c.alternate_path IS NULL OR trim(c.alternate_path) = '' THEN 'no-alternate' WHEN c.disposition = 'remove' AND c.disposition_state = 'applied' THEN 'removed' WHEN p.control IS NULL AND lower(trim(c.alternate_path)) LIKE 'none needed%' AND c.evidence LIKE '%ALTERNATE-NOT-EXERCISABLE%' THEN 'not-exercisable' WHEN p.control IS NULL THEN 'no-probe' WHEN p.enabled <> 1 THEN 'probe-disabled' WHEN p.last_run_at IS NULL THEN 'probe-never-run' WHEN p.last_pass IS NOT 1 THEN 'probe-failing' WHEN p.last_pass_at IS NULL OR p.last_pass_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-480 minutes') THEN 'probe-stale' ELSE 'drilled' END AS drill_state FROM control_registry c LEFT JOIN control_alternate_probes p ON p.control = c.control; DROP VIEW IF EXISTS v_path_coverage_gaps; CREATE VIEW v_path_coverage_gaps AS SELECT 'control_registry' AS source, control AS process, kind AS path_kind, CASE WHEN alternate_path IS NULL OR trim(alternate_path) = '' THEN 'no-alternate' WHEN alternate_tested_at IS NULL AND lower(trim(alternate_path)) LIKE 'none needed%' AND evidence LIKE '%ALTERNATE-NOT-EXERCISABLE%' THEN 'alternate-not-exercisable' WHEN alternate_tested_at IS NULL THEN 'alternate-untested' ELSE 'ok' END AS path_state, alternate_path AS alternate, alternate_tested_at FROM control_registry UNION ALL SELECT 'process_contracts' AS source, process, 'contract-paths' AS path_kind, CASE WHEN json_valid(paths_json) = 0 THEN 'paths-not-json' WHEN json_array_length(paths_json) < 2 THEN 'single-path' WHEN json_array_length(paths_json) = 2 THEN 'two-paths-no-spare' ELSE 'ok' END AS path_state, NULL AS alternate, NULL AS alternate_tested_at FROM process_contracts ; UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM remediation_contracts WHERE class = ''fm-trigger-depth-compile'' AND status = ''active'') THEN ''the fm-trigger-depth-compile detector contract is missing or not active'' WHEN COALESCE((SELECT last_verdict FROM remediation_contracts WHERE class = ''fm-trigger-depth-compile''), '''') <> ''pass'' THEN ''the fm-trigger-depth-compile detector does not read pass'' ELSE ''ok'' END AS observed', window_note = 'the contract runs hourly; its latest verdict is the evidence the rule''s alternate (a recurrence re-activates the group) is not hiding a depth fault' WHERE control = 'cf-obs-nested-too-deep-pin' AND instr(probe_sql, 'remediation_verifications') > 0
-- Rollback note: the decision_log row stays (append-only), and an alternate_tested_at the drill stamped on a passing probe stays (it was earned).

CREATE TABLE IF NOT EXISTS bak_20261019_path_alt_views AS SELECT name, sql, strftime('%Y-%m-%dT%H:%M:%SZ', 'now') AS backed_up_at FROM sqlite_master WHERE type = 'view' AND name IN ('v_path_coverage_gaps', 'v_control_alternate_status');

INSERT OR IGNORE INTO control_alternate_probes (control, probe_sql, window_note, enabled) VALUES
 ('code-task-publish-patch-cap',
  'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM code_tasks WHERE status = ''publish_failed'' AND (last_error IS NULL OR trim(last_error) = '''') AND updated_at > strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-1440 minutes'')) THEN ''a publish_failed code task of the last 1440 minutes carries no reason, so a refusal by the patch cap would be silent'' WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE instr(title, ''LOOP-BREAKER-1: '') = 1 AND instr(title, ''publish: patch larger than'') > 0) THEN ''no LOOP-BREAKER-1 issue records an oversize refusal, so nothing shows that a refused patch reaches a session'' WHEN EXISTS (SELECT 1 FROM code_tasks t WHERE t.last_error LIKE ''publish: patch larger than%'' AND t.updated_at > strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-1440 minutes'') AND t.updated_at < strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-120 minutes'') AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE instr(a.title, ''LOOP-BREAKER-1: '' || t.path || '':'') = 1) GROUP BY t.path HAVING COUNT(*) >= 3) THEN ''a path with three oversize refusals older than 120 minutes has no LOOP-BREAKER-1 issue, so the hand-off to a session did not happen'' WHEN EXISTS (SELECT 1 FROM (SELECT strftime(''%Y-%m-%dT%H:%M:%SZ'', created_at / 1000, ''unixepoch'') AS filed FROM agent_issues WHERE status = ''open'' AND instr(title, ''LOOP-BREAKER-1: '') = 1 AND instr(title, ''publish: patch larger than'') > 0) f WHERE f.filed < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-120 minutes'') AND NOT EXISTS (SELECT 1 FROM work_claims w WHERE (substr(w.holder, 1, 8) = ''session_'' OR substr(w.holder, 1, 14) = ''claude-session'') AND w.pr IS NOT NULL AND w.outcome = ''merged'' AND w.released_at > f.filed)) THEN ''a LOOP-BREAKER-1 oversize hand-off has been open for more than 120 minutes and no session pull request has merged since it was filed, so the alternate route was handed a change and has not carried it'' ELSE ''ok'' END AS observed',
  '1440 minutes for a failure without a reason and for three oversize refusals on one path (the loop breaker''s own threshold) to reach a LOOP-BREAKER-1 issue after a 120 minute grace, and 120 minutes for an open LOOP-BREAKER-1 oversize issue to be carried by a session pull request that merged after the issue was filed (nothing is owed while no such issue is open, so a quiet period with no session merge passes): the cap itself is MAX_PATCH in scripts/code-task-publish.py and is pinned by that script''s self-test, and a refused patch is the code loop handing the file to a session, which the issue and the merged session claim show', 1),
 ('relapse-reopen-window',
  'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM sqlite_master WHERE type = ''trigger'' AND name = ''remediation_reopen_on_relapse_d1'' AND tbl_name = ''remediation_verifications'' AND instr(sql, ''issue_lifecycle'') > 0) THEN ''the D1 trigger remediation_reopen_on_relapse_d1 is missing or no longer starts its window at the issue_lifecycle close event'' WHEN NOT EXISTS (SELECT 1 FROM sqlite_master WHERE type = ''view'' AND name = ''v_closure_relapses'' AND instr(sql, ''issue_lifecycle'') > 0) THEN ''the view v_closure_relapses is missing or no longer reads the close event'' WHEN NOT EXISTS (SELECT 1 FROM remediation_contracts WHERE class = ''fm-relapse-window-close-anchor'' AND status = ''active'' AND instr(verify_probe, ''issue_lifecycle'') > 0) THEN ''the detector fm-relapse-window-close-anchor is missing, not active or no longer reads the close event'' WHEN COALESCE((SELECT last_attempt_at FROM remediation_contracts WHERE class = ''fm-relapse-window-close-anchor''), '''') < datetime(''now'', ''-120 minutes'') THEN ''the detector fm-relapse-window-close-anchor did not run in 120 minutes'' WHEN NOT EXISTS (SELECT 1 FROM remediation_verifications WHERE verified_at > datetime(''now'', ''-120 minutes'')) THEN ''no verification row was written in 120 minutes, so the trigger has no feed'' WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE instr(description, ''REMEDIATION-REOPEN-2, D1 trigger'') > 0) THEN ''the trigger has never reopened an issue, so its reopen path has not run end to end'' ELSE ''ok'' END AS observed',
  '120 minutes: the verification feed and the detector contract run every few minutes, the trigger and view texts are state checks, and the trigger has reopened an issue before (60 rows on 2026-10-19), so the reopen path has run end to end', 1),
 ('verification-deferral-escalation',
  'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM pragma_table_info(''remediation_contracts'') WHERE name = ''deferred_since'') THEN ''remediation_contracts has no deferred_since column, so a deferral has no age to escalate or to count'' WHEN NOT EXISTS (SELECT 1 FROM remediation_contracts WHERE class = ''fm-verification-deferral-unaged'' AND status = ''active'' AND instr(verify_probe, ''deferred_since'') > 0 AND instr(verify_probe, ''VERIFICATION-DEFERRED-7D-1: '') > 0) THEN ''the detector fm-verification-deferral-unaged is missing, not active or no longer counts deferred_since against the escalation issue'' WHEN COALESCE((SELECT last_attempt_at FROM remediation_contracts WHERE class = ''fm-verification-deferral-unaged''), '''') < datetime(''now'', ''-120 minutes'') THEN ''the detector fm-verification-deferral-unaged did not run in 120 minutes'' WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE instr(title, ''VERIFICATION-DEFERRED-7D-1: '') = 1) THEN ''no escalation issue VERIFICATION-DEFERRED-7D-1 was ever filed, so the detector has never been shown to count the same rows as the escalation'' ELSE ''ok'' END AS observed',
  '120 minutes for the detector run (its contract is due about every 20 minutes), state checks on the deferred_since column and on the detector text, and one escalation issue exists: the control and the detector read the same column and the same issue title prefix', 1),
 ('improvement-loop-relapse-trigger-judge',
  'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''fix_target_hold_rate_30d'' AND kind = ''guard'') THEN ''the guard metric fix_target_hold_rate_30d is missing from metric_registry, so the target-based reading the judge falls back on is gone'' WHEN COALESCE((SELECT last_refreshed FROM metric_registry WHERE metric = ''fix_target_hold_rate_30d''), '''') < strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-120 minutes'') THEN ''fix_target_hold_rate_30d was not refreshed in 120 minutes'' WHEN NOT COALESCE((SELECT CAST(last_value AS REAL) BETWEEN 0 AND 1 FROM metric_registry WHERE metric = ''fix_target_hold_rate_30d'' AND last_value GLOB ''[0-9]*''), 0) THEN ''fix_target_hold_rate_30d holds no figure between 0 and 1'' WHEN COALESCE((SELECT ts FROM improvement_loop_runs ORDER BY id DESC LIMIT 1), '''') < strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-120 minutes'') THEN ''the improvement loop recorded no run in 120 minutes'' WHEN instr(COALESCE((SELECT state_json FROM improvement_loop_runs ORDER BY id DESC LIMIT 1), ''''), ''"fix_target_hold_rate_30d"'') = 0 THEN ''the latest improvement loop run no longer keeps the target-based figure in its state'' ELSE ''ok'' END AS observed',
  '120 minutes: fix_target_hold_rate_30d is refreshed hourly and improvement_loop_runs gets a row hourly, and the run state keeps the target-based figure the judge falls back on (ops_config il_relapse_trigger_judge is absent while the judge is on)', 1);

