WHERE control IN ('code-task-publish-patch-cap', 'relapse-reopen-window', 'verification-deferral-escalation', 'improvement-loop-relapse-trigger-judge') AND evidence NOT LIKE '%CONTROL-ALT-PROBES-3 2026-10-19%';

