  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'belief', datetime('now')),
 ('belief-alt-unexercisable-research-model-skip-gauge', NULL, 'DOCTRINE-1 belief (CONTROL-ALT-PROBES-3)', 'belief probe',
  'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''ai-skip'') THEN ''an ai-skip event now exists, so the research model skip gauge has tripped and its fallback or wait can be read as an event in a window: add a control_alternate_probes row for research-model-skip-gauge and retire its ALTERNATE-NOT-EXERCISABLE reason'' WHEN EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''ai-warn'' AND text LIKE ''%no fallback at or under its price%'') THEN ''an ai-warn event with no fallback at or under its price now exists, so the wait path has run: add a control_alternate_probes row for research-model-skip-gauge and retire its ALTERNATE-NOT-EXERCISABLE reason'' ELSE ''ok'' END AS observed',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'belief', datetime('now')),
 ('belief-alt-unexercisable-research-fallback-price-guard', NULL, 'DOCTRINE-1 belief (CONTROL-ALT-PROBES-3)', 'belief probe',
  'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''ai-warn'' AND text LIKE ''%no fallback at or under its price%'') THEN ''an ai-warn event with no fallback at or under its price now exists, so the wait path of the price guard has run: add a control_alternate_probes row for research-fallback-price-guard and retire its ALTERNATE-NOT-EXERCISABLE reason'' WHEN EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''ai-skip'') THEN ''an ai-skip event now exists, so a rate limited call has met the gauge and the price guard can be read as an event in a window: add a control_alternate_probes row for research-fallback-price-guard and retire its ALTERNATE-NOT-EXERCISABLE reason'' ELSE ''ok'' END AS observed',
