-- The doer for the one alternate that cannot be observed at all. Single-row VALUES insert (the open title is unique, so a second apply files nothing), then the probe on its birth contract.
INSERT OR IGNORE INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) VALUES (
 'MODEL-FLOOR-GUARD-OBSERVABLE-1: the model-floor-guard workflow leaves no D1 record of a green run, so the alternate of model_floor_pr_check cannot be probed',
 'Charter pillar: autonomy. CONTROL-ALT-PROBES-3 (migrations/2026-10-19-control-alternate-probes3.sql, agent_issues 2826 and 2880) records ALTERNATE-NOT-EXERCISABLE on control_registry.model_floor_pr_check because the alternate of that control, the post-merge push run and the 2-hourly schedule of the model-floor-guard workflow (.github/workflows/model-floor-guard.yml), leaves no trace in qnfo-audit. Read-only on 2026-10-19: no table or view of workflow runs, and github_steward_runs.detail keeps the workflow only as a notification when a run fails. A green run leaves nothing, so a probe could only pass by absence and would stamp a declaration. The reason is time-bound: the belief alt-unexercisable-model_floor_pr_check fails the moment a record exists, and fm-control-alternate-reason-unread then reads it. This issue builds the record and then retires the reason.' || char(10) ||
 'Step 1 (code-task, qnfo-github-steward, minor bump: a new data product): add a function modelFloorGuardVisibility(env, result) beside mainRulesVisibility that reads GET /repos/QNFO/qnfo-workers/actions/workflows/model-floor-guard.yml/runs?branch=main&status=completed&per_page=10 (the steward already reads workflow runs in triageNotifications) and sets result.model_floor_guard to an object with status, runs, last_conclusion, last_run_at, last_success_at and last_failure_at. Call it after mainRulesVisibility with the same try and catch shape, so the key reaches github_steward_runs.detail on every reconcile run. Bump var VERSION, keep deployed-current.worker.js identical, and put the release note where the VERSION-LINE-NOTES-1 mechanism keeps it. Add a test case that feeds a success and a failure run and reads both fields.' || char(10) ||
 'Step 2 (migration, a session or the code loop once step 1 is live): add a control_alternate_probes row for model_floor_pr_check that reads the model_floor_guard key of the newest github_steward_runs row, with every window in minutes and none above 120, as in migrations/2026-10-19-control-alternate-probes3.sql. A control with a probe row is judged by the probe in v_path_coverage_gaps and v_control_alternate_status, so the reason stops excusing it, and the belief and the detector stop naming it. Step 1 turns the belief falsified on purpose: its observed text is the cue for this step.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-github-steward/worker.js' || char(10) ||
 'code-anchor: try { await mainRulesVisibility(env, result); } catch (eM) {' || char(10) ||
 'Definition of done: github_steward_runs holds a row of the last 120 minutes whose detail carries the model_floor_guard key, and control_alternate_probes holds an enabled row for model_floor_pr_check. The d1-query contract on this issue reads both.',
 'claude-session:session_01QpQv19uh1padRwZ3u1r766', 'reliability', 'medium', 'open',
 CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000);

UPDATE remediation_contracts SET
  verify_probe = 'SELECT ''1'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM github_steward_runs WHERE instr(detail, ''"model_floor_guard"'') > 0 AND started_at > strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-120 minutes'')) AND EXISTS (SELECT 1 FROM control_alternate_probes WHERE control = ''model_floor_pr_check'' AND enabled = 1) THEN ''1'' ELSE ''0'' END AS observed',
  verify_transport = 'd1-query', status = 'active', last_verdict = NULL, attempts = 0, next_due_at = NULL, module = 'control-alt-probes',
  precondition = 'the model-floor-guard workflow leaves no D1 record of a green run and model_floor_pr_check has no alternate probe',
  action = 'qnfo-github-steward records the newest model-floor-guard runs in github_steward_runs.detail, then a migration adds the control_alternate_probes row for model_floor_pr_check',
  escalate_to = 'qnfo-fleet-control', expected_cadence_h = 1
 WHERE class = 'issue-' || (SELECT MAX(id) FROM agent_issues WHERE title LIKE 'MODEL-FLOOR-GUARD-OBSERVABLE-1:%' AND status = 'open')
   AND COALESCE(module, '') <> 'control-alt-probes'
   AND EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'MODEL-FLOOR-GUARD-OBSERVABLE-1:%' AND status = 'open');

DROP VIEW IF EXISTS v_control_alternate_status;
CREATE VIEW v_control_alternate_status AS
SELECT c.control AS control, c.critical_path AS critical_path, c.disposition AS disposition, c.disposition_state AS disposition_state,
  c.alternate_path AS alternate_path, c.alternate_tested_at AS alternate_tested_at,
  p.enabled AS probe_enabled, p.last_run_at AS last_run_at, p.last_pass AS last_pass, p.last_pass_at AS last_pass_at, p.last_observed AS last_observed,
  p.window_note AS window_note,
  CASE
    WHEN c.alternate_path IS NULL OR trim(c.alternate_path) = '' THEN 'no-alternate'
    WHEN c.disposition = 'remove' AND c.disposition_state = 'applied' THEN 'removed'
    WHEN p.control IS NULL AND c.evidence LIKE '%ALTERNATE-NOT-EXERCISABLE%' THEN 'not-exercisable'
    WHEN p.control IS NULL THEN 'no-probe'
    WHEN p.enabled <> 1 THEN 'probe-disabled'
    WHEN p.last_run_at IS NULL THEN 'probe-never-run'
    WHEN p.last_pass IS NOT 1 THEN 'probe-failing'
    WHEN p.last_pass_at IS NULL OR p.last_pass_at < strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-480 minutes') THEN 'probe-stale'
    ELSE 'drilled'
  END AS drill_state
FROM control_registry c LEFT JOIN control_alternate_probes p ON p.control = c.control;

DROP VIEW IF EXISTS v_path_coverage_gaps;
CREATE VIEW v_path_coverage_gaps AS
SELECT
  'control_registry' AS source,
  control AS process,
  kind AS path_kind,
  CASE
    WHEN alternate_path IS NULL OR trim(alternate_path) = '' THEN 'no-alternate'
    WHEN alternate_tested_at IS NULL AND evidence LIKE '%ALTERNATE-NOT-EXERCISABLE%' AND NOT EXISTS (SELECT 1 FROM control_alternate_probes p WHERE p.control = control_registry.control) THEN 'alternate-not-exercisable'
    WHEN alternate_tested_at IS NULL THEN 'alternate-untested'
    ELSE 'ok'
  END AS path_state,
  alternate_path AS alternate,
  alternate_tested_at
FROM control_registry
UNION ALL
SELECT
  'process_contracts' AS source,
  process,
  'contract-paths' AS path_kind,
  CASE
    WHEN json_valid(paths_json) = 0 THEN 'paths-not-json'
    WHEN json_array_length(paths_json) < 2 THEN 'single-path'
    WHEN json_array_length(paths_json) = 2 THEN 'two-paths-no-spare'
    ELSE 'ok'
  END AS path_state,
  NULL AS alternate,
  NULL AS alternate_tested_at
FROM process_contracts;

-- CF-OBS-NESTED-TOO-DEEP-PIN probe restated over a 120 minute window (CHAOS-DRILL-FAILED-1 issue 100247, found by session_01JADz8u at the first control drill, 18:00:34Z):
-- the seeded probe read the last verdict of the fm-trigger-depth-compile detector, whose own window is 25 minutes, so it flapped between passes (the trigger-depth sweep wrote passes at
-- 17:24:12Z and 17:54:15Z and nothing between). It now asks for a passing verification inside 120 minutes. Guarded so a replay, or a row someone already restated, is left alone.
UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM remediation_contracts WHERE class = ''fm-trigger-depth-compile'' AND status = ''active'') THEN ''the fm-trigger-depth-compile detector contract is missing or not active'' WHEN NOT EXISTS (SELECT 1 FROM remediation_verifications WHERE class = ''fm-trigger-depth-compile'' AND pass = 1 AND replace(substr(verified_at, 1, 19), ''T'', '' '') > datetime(''now'', ''-120 minutes'')) THEN ''the fm-trigger-depth-compile detector has no passing verification in 120 minutes'' ELSE ''ok'' END AS observed', window_note = '120 minutes: the fm-trigger-depth-compile detector must have a passing verification in the last 120 minutes; its own window is 25 minutes and the sweep verifies it about twice an hour, so reading only its last verdict flapped (CHAOS-DRILL-FAILED-1 issue 100247, 6 of 7 passed in the 17:00Z hour)'
WHERE control = 'cf-obs-nested-too-deep-pin' AND instr(probe_sql, 'last_verdict') > 0;

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('control-alternate-reason-unread', 'a control records ALTERNATE-NOT-EXERCISABLE and the path views still list it as untested, or the marker clears a control with no review, or its premise has stopped holding and nothing notices',
  'v_path_coverage_gaps and v_control_alternate_status excused a row only when its alternate_path started with none needed, so three rows with a recorded reason stayed alternate-untested and fm-control-alternate-undrilled kept counting them (agent_issues 2826). Widening the views made the bare token a free exemption for any probe-less control (a text edit of control_registry.evidence, with no blocker_redteam row required), and the reasons are dated measurements (0 ai-skip events, a green workflow run leaves no record) with no belief that breaks when they stop holding',
  'both views read the marker on any row that has no probe, the fm- detector compares the register with both views every hour and requires a confirmed blocker_redteam row per marker, and each reason has a belief alt-unexercisable-<control> that the detector reads (CONTROL-ALT-PROBES-3)',
  'the fm-control-alternate-reason-unread contract counts controls with the marker, no probe and no tested date that either view does not read as not exercisable, that have no confirmed blocker_redteam row control:<name> (a none needed alternate_path keeps its CONTROL-ALT-PROBES-1 standing), or whose belief alt-unexercisable-<name> reads falsified',
  'fm-control-alternate-reason-unread', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), 2826,
  'a control_registry row with ALTERNATE-NOT-EXERCISABLE in evidence, no control_alternate_probes row and no alternate_tested_at that v_path_coverage_gaps or v_control_alternate_status still reads as a gap, that has no confirmed red-team row, or whose premise belief is falsified',
  'v_path_coverage_violations alternate-untested for a row whose reason is recorded, controls_untested_without_probe above the number of controls with neither a probe nor a reviewed reason, or a reason that stays in force after its premise broke',
  'the path coverage views, fm-control-alternate-undrilled and the control-alternate-probes probe');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-control-alternate-reason-unread', NULL, 'CONTROL-ALT-PROBES-3', 'failure-mode detector',
  'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM control_registry c WHERE trim(COALESCE(c.alternate_path, '''')) <> '''' AND c.alternate_tested_at IS NULL AND NOT (c.disposition = ''remove'' AND c.disposition_state = ''applied'') AND c.evidence LIKE ''%ALTERNATE-NOT-EXERCISABLE%'' AND NOT EXISTS (SELECT 1 FROM control_alternate_probes p WHERE p.control = c.control) AND (COALESCE((SELECT g.path_state FROM v_path_coverage_gaps g WHERE g.source = ''control_registry'' AND g.process = c.control), '''') <> ''alternate-not-exercisable'' OR COALESCE((SELECT s.drill_state FROM v_control_alternate_status s WHERE s.control = c.control), '''') <> ''not-exercisable'' OR (lower(trim(c.alternate_path)) NOT LIKE ''none needed%'' AND (NOT EXISTS (SELECT 1 FROM blocker_redteam b WHERE b.target = ''control:'' || c.control AND b.verdict = ''confirmed-with-evidence'') OR EXISTS (SELECT 1 FROM v_belief_status f WHERE f.belief_key = ''alt-unexercisable-'' || c.control AND f.status = ''falsified''))))) AS TEXT) AS observed',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now'));

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session_01QpQv19uh1padRwZ3u1r766',
  'a control alternate counts as tested only while a probe on its own evidence keeps passing, a control whose alternate leaves no trace in D1 is said so with its reason instead of getting a probe that passes by absence, and the register must read that reason for every such row and not only for rows whose alternate_path starts with none needed',
  'CONTROL-ALT-PROBES-3: four read-only expected/observed probes in control_alternate_probes (code-task-publish-patch-cap, relapse-reopen-window, verification-deferral-escalation, improvement-loop-relapse-trigger-judge), ALTERNATE-NOT-EXERCISABLE recorded for model_floor_pr_check, research-model-skip-gauge and research-fallback-price-guard with a blocker_redteam row each, and v_path_coverage_gaps and v_control_alternate_status read that marker on any row without a probe. After review: the detector requires a confirmed blocker_redteam row per marker (a text edit alone no longer clears a control), each reason has a belief alt-unexercisable-<control> with a belief-<key> contract that fails when its premise breaks and that the detector reads, and the one alternate that cannot be observed at all has a doer, agent_issues MODEL-FLOOR-GUARD-OBSERVABLE-1',
  'qnfo-audit 2026-10-19 18:1xZ (SELECT only): v_control_alternate_untested controls_untested_without_probe 7, critical_untested_by_register 1 (code-task-publish-patch-cap), drill_state drilled 30, no-probe 65, probe-failing 2 (control-alternate-probes on the same 7), the chaos drill ran at about 18:00Z on qnfo-fleet-control 0.40.0; the four probes returned ok when run read-only; ai-skip events ever 0, workflow-run tables 0, 3021 or 3040 rate limits 4132 on 2026-10-17 and 2026-10-18 and 1 on 2026-10-19; the three premise probes returned ok when run read-only, and no live row of github_steward_runs carries the model_floor_guard key',
  'migration merged',
  'four control_alternate_probes rows, evidence text on seven control_registry rows, three blocker_redteam rows, three belief_registry rows with three belief-<key> contracts, one agent_issues row with its contract probe, one failure mode with its fm- detector contract, two redefined views (same columns, readers v_path_coverage_violations and v_control_alternate_untested unchanged), one backup table, no worker change and no alternate_tested_at written',
  'the Rollback header of migrations/2026-10-19-control-alternate-probes3.sql',
  'every registered control with an alternate is either probed by the drill or says why no probe can exist, and the register shows the difference',
  'controls_on_critical_path_untested <= 0 within 12 h',
  'none',
  'd1:qnfo-audit read-only probe runs and schema reads (cloud_ops_events, sqlite_master, github_steward_runs, agent_issues unique indexes and birth trigger), node:sqlite fixtures in migrations/control-alternate-probes3.test.mjs'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE action LIKE 'CONTROL-ALT-PROBES-3:%');
